//! Shared domain and event types. This file is the contract between the Rust core,
//! the adapters, and the Svelte UI (TypeScript bindings are generated by ts-rs into
//! `src/lib/gen/` when `cargo test -p codly-core` runs).
//!
//! Rules:
//! - Every type that crosses the IPC boundary derives `TS` + `#[ts(export)]`.
//! - Enums serialize as snake_case strings; tagged unions use `type` (events) or `kind`.
//! - IDs are UUIDv7 strings (time-sortable). Timestamps are unix epoch milliseconds.

use serde::{Deserialize, Serialize};
use serde_json::Value;
use ts_rs::TS;

pub type Id = String;

pub fn new_id() -> Id {
    uuid::Uuid::now_v7().to_string()
}

pub fn default_lead_thread() -> String {
    "lead".into()
}

/// Request threads: "lead" (the first) and "lead:<id>" (parallel requests, each with its own
/// Lead session). 1:1 agent threads are "agent:<id>".
pub fn is_lead_thread(thread: &str) -> bool {
    thread == "lead" || thread.starts_with("lead:")
}

pub fn now_ms() -> i64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_millis() as i64)
        .unwrap_or(0)
}

// ───────────────────────────── providers & CLIs ─────────────────────────────

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize, TS)]
#[serde(rename_all = "snake_case")]
#[ts(export)]
pub enum Provider {
    Claude,
    Codex,
    Gemini,
    Opencode,
    Cursor,
    Copilot,
}

impl Provider {
    pub const ALL: [Provider; 6] = [
        Provider::Claude,
        Provider::Codex,
        Provider::Gemini,
        Provider::Opencode,
        Provider::Cursor,
        Provider::Copilot,
    ];
    pub fn as_str(self) -> &'static str {
        match self {
            Provider::Claude => "claude",
            Provider::Codex => "codex",
            Provider::Gemini => "gemini",
            Provider::Opencode => "opencode",
            Provider::Cursor => "cursor",
            Provider::Copilot => "copilot",
        }
    }
    pub fn label(self) -> &'static str {
        match self {
            Provider::Claude => "Claude Code",
            Provider::Codex => "Codex",
            Provider::Gemini => "Gemini CLI",
            Provider::Opencode => "OpenCode",
            Provider::Cursor => "Cursor",
            Provider::Copilot => "Copilot",
        }
    }
}

/// Who pays for an agent's tokens. Shown as a badge on every agent.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "snake_case")]
#[ts(export)]
pub enum Billing {
    Subscription,
    ApiKey,
    ThirdParty,
    Unknown,
}

/// Result of detecting one agent CLI on this machine (env.rs).
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct CliInfo {
    pub provider: Provider,
    /// Absolute path of the resolved binary, if found.
    pub path: Option<String>,
    pub version: Option<String>,
    /// None = unknown (no cheap status command for this CLI).
    pub logged_in: Option<bool>,
    pub billing: Billing,
    /// Plan / account label, e.g. "team", "plus", "api key".
    pub plan: Option<String>,
    /// Human-readable problem, e.g. "not signed in: run `claude` once".
    pub problem: Option<String>,
    /// Integration path Codly uses, e.g. "stream-json", "app-server", "acp".
    pub transport: String,
    /// How to install and sign in this CLI (trusted constants, `install.rs`).
    pub install: InstallHint,
    /// The model it runs when Codly passes none (`env::default_model`): its config's, else its
    /// built-in default. None = it doesn't say (Claude Code picks by plan).
    #[serde(default)]
    pub default_model: Option<String>,
}

/// How to get one agent CLI onto this machine. Built from constants in `install.rs`, never from
/// user input; the UI shows these strings and asks `install_cli` to run them (by provider and
/// rung, not by text).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct InstallHint {
    /// Install through npm, if the vendor ships it that way.
    pub npm: Option<String>,
    /// The vendor's own installer script (macOS/Linux).
    pub native: Option<String>,
    /// The command that signs in (`env::login_command`), if there is one.
    pub login: Option<String>,
    /// The vendor's docs or home page.
    pub docs: String,
}

