#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "snake_case")]
#[ts(export)]
pub enum Role {
    /// The supervisor: chats with the user, plans, sees the whole board.
    Lead,
    Worker,
    Reviewer,
    /// A free agent the user chats with 1:1 (no task).
    Solo,
}

/// Coarse status. Five user-facing states map from this (working, waiting on you,
/// blocked, idle, done); the finer `Activity` says *what* the agent is doing.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "snake_case")]
#[ts(export)]
pub enum AgentStatus {
    Offline,
    Starting,
    Idle,
    Thinking,
    Working,
    WaitingApproval,
    Blocked,
    RateLimited,
    Done,
    Failed,
}

/// Normalized activity kinds (design-world §9.2). Drives the world and the timeline.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize, TS)]
#[serde(rename_all = "snake_case")]
#[ts(export)]
pub enum ActivityKind {
    Idle,
    Thinking,
    Replying,
    Read,
    Search,
    Edit,
    Create,
    Delete,
    Execute,
    Test,
    Fetch,
    Mcp,
    Plan,
    Delegate,
    Message,
    Note,
    Memory,
    Review,
    Commit,
    Merge,
    AwaitApproval,
    Blocked,
    Retrying,
    RateLimited,
    Compacting,
    Done,
}

/// What a tool call targets. All fields optional; adapters fill what they know.
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct Target {
    pub path: Option<String>,
    pub paths: Vec<String>,
    pub command: Option<String>,
    pub query: Option<String>,
    pub url: Option<String>,
    pub server: Option<String>,
    pub tool: Option<String>,
}

#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct Usage {
    pub input_tokens: i64,
    pub output_tokens: i64,
    pub cache_read_tokens: i64,
    pub cache_write_tokens: i64,
    /// Snapshot of the latest turn's context use (never a sum of turns).
    pub context_used: Option<i64>,
    pub context_window: Option<i64>,
    /// List-price estimate (Claude) or provider cost (OpenCode). Never a charge on a subscription.
    pub cost_usd: Option<f64>,
}

#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct Agent {
    pub id: Id,
    pub name: String,
    pub provider: Provider,
    pub model: Option<String>,
    pub role: Role,
    pub status: AgentStatus,
    /// Current activity (latest live tool call or state), for the world and inspector.
    pub activity: Option<ActivityKind>,
    /// Short human label of the activity target, e.g. "app.ts" or "npm test".
    pub activity_label: Option<String>,
    pub task_id: Option<Id>,
    pub run_id: Option<Id>,
    pub session_id: Option<String>,
    pub worktree: Option<String>,
    pub billing: Billing,
    /// Account (`AccountInfo::id`) of its current or last session. None = the provider's
    /// primary sign-in (agents from before accounts existed).
    #[serde(default)]
    pub account: Option<String>,
    /// Index into the 8 identity hues (`--id-1`..`--id-8`), stable per agent.
    pub color: i64,
    /// Seed for the procedural sprite (defaults to id).
    pub look_seed: String,
    /// Lead agents only: the request thread this Lead serves ("lead" or "lead:<id>").
    #[serde(default)]
    pub thread: Option<String>,
    /// Team members only: `TeamMember::id`.
    #[serde(default)]
    pub member: Option<String>,
    /// Job title (badge): a team member's, a consultant's (the Lead's pick) or a 1:1 agent's.
    #[serde(default)]
    pub title: Option<String>,
    /// Hired for one task; let go when it ends.
    #[serde(default)]
    pub consultant: bool,
    /// You brought it back from the ghosts: it stays between tasks until you let it go.
    #[serde(default)]
    pub kept: bool,
    /// Let go (fired consultant, removed member, closed Lead): gone from the team.
    #[serde(default)]
    pub archived: bool,
    pub usage: Usage,
    /// Track record, rank and traits; kept for good and carried along when exported.
    #[serde(default)]
    pub career: Career,
    /// Gone home to rest (the office's energy) until then (ms). The Lead gives it no new work
    /// meanwhile; you still can. Its conversation and session are untouched.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[ts(optional)]
    pub away_until: Option<i64>,
    /// When it left for home (ms), set with `away_until`: the map walks it down the street then.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[ts(optional)]
    pub away_since: Option<i64>,
    /// Tired since then (ms): the office's energy fell under 30% (it reports crossing back).
    /// Only a hint: the Lead and the scheduler prefer someone rested, never refuse it work.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[ts(optional)]
    pub tired_since: Option<i64>,
    pub created_at: i64,
    pub updated_at: i64,
}

