/// Seniority, earned from real work (`career.rs` has the XP rules).
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize, TS)]
#[serde(rename_all = "snake_case")]
#[ts(export)]
pub enum Rank {
    #[default]
    Intern,
    Junior,
    Senior,
    Staff,
}

#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct CareerStats {
    pub commits: i64,
    pub checks_passed: i64,
    pub checks_failed: i64,
    pub approved: i64,
    pub changes_requested: i64,
    pub reviews_done: i64,
    pub merged: i64,
    /// Shifts it worked and then went home to rest (reported by the office).
    #[serde(default)]
    pub shifts: i64,
    /// Times it got sick: too much coffee, not enough sleep (reported by the office).
    #[serde(default)]
    pub sick: i64,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct Milestone {
    pub at: i64,
    pub text: String,
}

/// An agent's track record. Everything here comes from its real events, except `traits`
/// (picked at hiring); it survives restarts and travels with an exported agent.
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct Career {
    pub xp: i64,
    pub rank: Rank,
    pub stats: CareerStats,
    /// XP per area ("Rust", "Testing"…), from the files it changed.
    pub skills: std::collections::BTreeMap<String, i64>,
    /// Newest last, capped.
    pub milestones: Vec<Milestone>,
    /// Personality (`career::TRAITS` ids). Some change how it works; see `career::TRAITS`.
    pub traits: Vec<String>,
    /// The rank whose perks you granted (`career::PERKS`), never above `rank`. A promotion only
    /// offers it; it stays in this repo (an imported agent starts with none).
    #[serde(default)]
    pub trust: Rank,
    /// Reviews between it and other agents in this repo, by agent id (both ways). Repo-local:
    /// an imported agent starts with none.
    #[serde(default)]
    pub friends: std::collections::BTreeMap<String, i64>,
    /// The Senior or Staff whose reviews mentored it while it was an Intern or Junior.
    #[serde(default)]
    pub mentor: Option<Id>,
    /// 0 … 100, from its real days on the crew, merges and shifts (`career::stamina`): how
    /// slowly it tires, how fast it recovers, how much coffee it takes. Kept up to date by the core.
    #[serde(default)]
    pub stamina: i64,
    /// Legendary: the title above Staff (`career::legend_ok`); once earned, it stays.
    #[serde(default)]
    pub legend: bool,
}

/// One agent's work in a period (the daily edition and the morning standup).
