/// The canonical event. Adapters produce the provider kinds; the orchestrator adds the
/// domain kinds. Persisted to SQLite (except ephemeral deltas) and streamed to the UI.
/// Both views (Workspace and World) are projections of this stream.
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(tag = "type", rename_all = "snake_case")]
#[ts(export)]
pub enum EventKind {
    // ── provider events (from adapters) ──
    SessionStarted {
        provider: Provider,
        model: Option<String>,
        cwd: String,
        cli_version: Option<String>,
        session_id: Option<String>,
        billing: Billing,
        tools: Vec<String>,
    },
    TurnStarted {
        input: Option<String>,
    },
    StatusChanged {
        status: AgentStatus,
    },
    /// Ephemeral streaming text (not persisted; the final `Message` is).
    TextDelta {
        item_id: String,
        text: String,
    },
    Message {
        item_id: String,
        text: String,
        phase: MessagePhase,
    },
    /// Ephemeral reasoning/thought stream (not persisted; `Reasoning` is).
    ReasoningDelta {
        item_id: String,
        text: String,
    },
    Reasoning {
        item_id: String,
        text: String,
    },
    ToolStarted {
        call_id: String,
        /// Provider tool name ("Bash", "commandExecution", "read_file"…).
        name: String,
        activity: ActivityKind,
        target: Target,
        input: Value,
        /// "observed" when the provider said what it is; "inferred" when Codly classified it.
        confidence: String,
    },
    /// Ephemeral live output chunk (Codex outputDelta, ACP terminal delta).
    ToolOutput {
        call_id: String,
        chunk: String,
    },
    ToolCompleted {
        call_id: String,
        ok: bool,
        /// Truncated (≤ 8 KB head+tail) output.
        output: Option<String>,
        exit_code: Option<i64>,
        duration_ms: Option<i64>,
        /// Parsed test counts when the command was a test run (Inferred).
        tests_passed: Option<i64>,
        tests_failed: Option<i64>,
    },
    FilesChanged {
        call_id: Option<String>,
        paths: Vec<String>,
        /// "provider" | "tool_input" | "git"
        source: String,
    },
    /// The agent's own todo list (personal kanban).
    PlanUpdated {
        steps: Vec<PlanStep>,
    },
    ApprovalRequested {
        approval: Approval,
    },
    ApprovalResolved {
        approval_id: Id,
        status: ApprovalStatus,
        /// "user" | "policy" | "provider"
        by: String,
    },
    UsageUpdated {
        usage: Usage,
    },
    RateLimit {
        window: String,
        used_fraction: Option<f64>,
        resets_at: Option<i64>,
        status: Option<String>,
    },
    Retrying {
        attempt: i64,
        reason: String,
    },
    SubAgent {
        call_id: String,
        description: String,
        status: String,
    },
    Compacting {
        pre_tokens: Option<i64>,
        post_tokens: Option<i64>,
    },
    TurnCompleted {
        status: TurnStatus,
        result_text: Option<String>,
        duration_ms: Option<i64>,
    },
    Error {
        message: String,
        fatal: bool,
    },
    Exited {
        code: Option<i64>,
    },
    /// An event Codly does not understand yet (raw kept in the run log).
    Unknown {
        raw_type: String,
    },

    // ── Codly domain events (from the orchestrator) ──
    AgentChanged {
        agent: Agent,
    },
    PlanChanged {
        plan: Plan,
    },
    TaskChanged {
        task: Task,
    },
    Chat {
        message: ChatMessage,
    },
    /// A recorded orchestration decision (routing, scheduling, gate, merge) — the
    /// "Why?" behind everything the supervisor does.
    Decision {
        id: Id,
        decision_type: String,
        /// "rule" | "model" | "human"
        method: String,
        summary: String,
        detail: Value,
    },
    Retrieval {
        query: String,
        confidence: Confidence,
        citations: Vec<Citation>,
    },
    MemoryAdded {
        memory: Memory,
    },
    TripleAdded {
        triple: Triple,
    },
    Committed {
        sha: String,
        files: Vec<String>,
        message: String,
    },
    Verified {
        command: String,
        ok: bool,
        exit_code: Option<i64>,
        tail: String,
    },
    Reviewed {
        verdict: String,
        summary: String,
    },
    Merged {
        sha: String,
        branch: String,
    },
    ArtifactAdded {
        artifact: Artifact,
    },
    /// A job offer was posted, or closed with someone hired.
    JobOffer {
        offer: JobOffer,
    },
    /// An agent's live controls changed (block tools, stop after this step, held notes).
    ControlChanged {
        control: ControlState,
    },
    /// An "ask me" blocker was raised, answered, dismissed or reminded (codly_ask_user).
    BlockerChanged {
        blocker: crate::blockers::Blocker,
    },
}

impl EventKind {
    /// Ephemeral events are streamed to the UI but never persisted (id = 0).
    pub fn is_ephemeral(&self) -> bool {
        matches!(
            self,
            EventKind::TextDelta { .. } | EventKind::ReasoningDelta { .. } | EventKind::ToolOutput { .. }
        )
    }

    pub fn type_name(&self) -> &'static str {
        match self {
            EventKind::SessionStarted { .. } => "session_started",
            EventKind::TurnStarted { .. } => "turn_started",
            EventKind::StatusChanged { .. } => "status_changed",
            EventKind::TextDelta { .. } => "text_delta",
            EventKind::Message { .. } => "message",
            EventKind::ReasoningDelta { .. } => "reasoning_delta",
            EventKind::Reasoning { .. } => "reasoning",
            EventKind::ToolStarted { .. } => "tool_started",
            EventKind::ToolOutput { .. } => "tool_output",
            EventKind::ToolCompleted { .. } => "tool_completed",
            EventKind::FilesChanged { .. } => "files_changed",
            EventKind::PlanUpdated { .. } => "plan_updated",
            EventKind::ApprovalRequested { .. } => "approval_requested",
            EventKind::ApprovalResolved { .. } => "approval_resolved",
            EventKind::UsageUpdated { .. } => "usage_updated",
            EventKind::RateLimit { .. } => "rate_limit",
            EventKind::Retrying { .. } => "retrying",
            EventKind::SubAgent { .. } => "sub_agent",
            EventKind::Compacting { .. } => "compacting",
            EventKind::TurnCompleted { .. } => "turn_completed",
            EventKind::Error { .. } => "error",
            EventKind::Exited { .. } => "exited",
            EventKind::Unknown { .. } => "unknown",
            EventKind::AgentChanged { .. } => "agent_changed",
            EventKind::PlanChanged { .. } => "plan_changed",
            EventKind::TaskChanged { .. } => "task_changed",
            EventKind::Chat { .. } => "chat",
            EventKind::Decision { .. } => "decision",
            EventKind::Retrieval { .. } => "retrieval",
            EventKind::MemoryAdded { .. } => "memory_added",
            EventKind::TripleAdded { .. } => "triple_added",
            EventKind::Committed { .. } => "committed",
            EventKind::Verified { .. } => "verified",
            EventKind::Reviewed { .. } => "reviewed",
            EventKind::Merged { .. } => "merged",
            EventKind::ArtifactAdded { .. } => "artifact_added",
            EventKind::JobOffer { .. } => "job_offer",
            EventKind::ControlChanged { .. } => "control_changed",
            EventKind::BlockerChanged { .. } => "blocker_changed",
        }
    }
}

/// One row of the event log (and one item of a UI batch).
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct EventRow {
    /// Global monotonic id (SQLite rowid). 0 for ephemeral events.
    pub id: i64,
    pub ts: i64,
    pub agent_id: Option<Id>,
    pub task_id: Option<Id>,
    pub run_id: Option<Id>,
    /// The office it happened in, on the live stream only (None for app-wide events).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    #[ts(optional)]
    pub workspace_id: Option<Id>,
    pub kind: EventKind,
}

// ───────────────────────────── workspace, settings, snapshot ─────────────────────────────

#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct Workspace {
    pub id: Id,
    pub repo_path: String,
    pub name: String,
    pub default_branch: String,
    pub current_branch: Option<String>,
    pub head: Option<String>,
    pub dirty: bool,
    pub created_at: i64,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "snake_case")]
#[ts(export)]
pub enum ApprovalMode {
    /// Codly rules decide the obvious cases; everything else asks you.
    Balanced,
    /// Ask for every command and edit the CLI would ask about.
    Strict,
    /// Allow everything that stays inside the agent's worktree.
    Autonomous,
    /// Auto-approve everything, risky commands included, except the hard floors: questions,
    /// permission changes, writes by read-only agents and Codly's own data dir still ask.
    Full,
}

/// How a request's Lead turns work into changes (picked per request in the composer).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "snake_case")]
#[ts(export)]
pub enum LeadMode {
    /// Answers only: no plans, no tasks.
    Ask,
    /// Proposes a plan; you start it with Run plan.
    Plan,
    /// Plans and runs them at once.
    Auto,
    /// No plan card: hands the work straight to a team member or consultant, started at once.
    Direct,
}

/// A request's own choices, each None = the Settings default.
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize, TS)]
#[serde(default)]
#[ts(export)]
pub struct RequestPrefs {
    pub mode: Option<LeadMode>,
    pub approval_mode: Option<ApprovalMode>,
    /// The Lead's model, "opus:high" style.
    pub model: Option<String>,
    /// The Lead's CLI for this request (its model belongs to it).
    pub provider: Option<Provider>,
}

#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct Settings {
    pub lead_provider: Option<Provider>,
    pub lead_model: Option<String>,
    /// Providers workers may use, in preference order.
    pub worker_providers: Vec<Provider>,
    pub max_parallel: i64,
    /// Workers at once per account (per provider when it has a single sign-in).
    pub max_per_provider: i64,
    /// Sign-ins per CLI and which ones Codly may use, in preference order. A provider with
    /// none listed uses your login shell's sign-in.
    #[serde(default)]
    pub accounts: Vec<AccountConfig>,
    #[serde(default)]
    pub account_strategy: AccountStrategy,
    /// Account the Lead runs on (None = the one with the most quota left).
    #[serde(default)]
    pub lead_account: Option<String>,
    pub approval_mode: ApprovalMode,
    /// Run plans without waiting for the "Run plan" click.
    pub auto_run_plans: bool,
    /// Cross-vendor reviewer gate before merge.
    pub review_gate: bool,
    /// The Lead receives task/plan status updates as turns.
    pub lead_followups: bool,
    /// Ambient (non-event) motion in the world. Off = honest by default.
    pub world_ambient: bool,
    /// "system" | "dark" | "light"
    pub theme: String,
    /// The standing team, in every repo unless a repo switches a member off.
    #[serde(default)]
    pub team: Vec<TeamMember>,
    /// Opt in to your own OpenRouter key for OpenCode (the key itself lives in the Keychain).
    /// Off = subscription-only: every API-key variable is scrubbed from the agents' env.
    #[serde(default)]
    pub byok_openrouter: bool,
    /// Claude agents also load your own Claude Code setup: your MCP servers, plugins, skills
    /// and the repo's `.claude` settings. Off = Codly's own tools and Connections only.
    #[serde(default = "yes")]
    pub use_my_claude_setup: bool,
    /// Pause (the office's speed control): no new task starts; running ones finish.
    #[serde(default)]
    pub paused: bool,
    /// Offices paused one by one (their own Pause, or their tab closed): the same rule, there only.
    #[serde(default)]
    pub paused_offices: Vec<Id>,
    /// The Settings' Developer panel: cheats for testing the game (coins, XP, a fresh office).
    /// Cheats flag the wallet for good.
    #[serde(default)]
    pub developer_mode: bool,
}

fn yes() -> bool {
    true
}

impl Default for Settings {
    fn default() -> Self {
        Settings {
            lead_provider: None,
            lead_model: None,
            worker_providers: vec![Provider::Claude, Provider::Codex, Provider::Gemini, Provider::Opencode],
            max_parallel: 3,
            max_per_provider: 2,
            accounts: vec![],
            account_strategy: AccountStrategy::Spread,
            lead_account: None,
            approval_mode: ApprovalMode::Balanced,
            auto_run_plans: false,
            review_gate: false,
            lead_followups: true,
            world_ambient: false,
            theme: "system".into(),
            team: vec![],
            byok_openrouter: false,
            use_my_claude_setup: true,
            paused: false,
            paused_offices: vec![],
            developer_mode: false,
        }
    }
}

/// Everything the UI needs on (re)connect. Deltas with `id <= as_of` are dropped.
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct Snapshot {
    pub as_of: i64,
    pub clis: Vec<CliInfo>,
    pub accounts: Vec<AccountInfo>,
    pub workspace: Option<Workspace>,
    pub settings: Settings,
    /// The open repo's changes to the global team.
    pub workspace_team: Option<WorkspaceTeam>,
    /// Per request thread of the open repo: its mode, permissions and Lead model.
    pub request_prefs: std::collections::HashMap<String, RequestPrefs>,
    pub agents: Vec<Agent>,
    pub plans: Vec<Plan>,
    pub tasks: Vec<Task>,
    pub approvals: Vec<Approval>,
    pub chats: Vec<ChatMessage>,
    pub memories: Vec<Memory>,
    pub triples: Vec<Triple>,
    pub artifacts: Vec<Artifact>,
    /// Most recent persisted events (for timeline, inspector and world replay).
    pub events: Vec<EventRow>,
}

/// Recent workspaces for the welcome screen.
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct RecentWorkspace {
    pub repo_path: String,
    pub name: String,
    pub opened_at: i64,
}

/// Another of your offices (a repo you opened before): where an agent can transfer to.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct Office {
    pub id: Id,
    pub name: String,
    pub repo_path: String,
    /// Agents working there, the Lead aside.
    pub crew: i64,
    /// Its tasks in flight now (running, in review or merging): each keeps an agent busy.
    pub working: i64,
    /// Its agents at home now (`Agent::away_until` still ahead): the map walks them home.
    #[serde(default)]
    pub home: Vec<AwayAgent>,
}

/// An agent at home, for the Neighbourhood map: when it left and when it is back (ms).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct AwayAgent {
    pub id: Id,
    pub name: String,
    /// Its identity hue (`Agent::color`).
    pub color: i64,
    pub since: Option<i64>,
    pub until: i64,
}

// ───────────────────────────── per-agent live controls ─────────────────────────────

/// What the agent panel shows: the controls an agent runs under right now.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize, TS)]
#[ts(export)]
pub struct ControlState {
    /// The agent may think and answer, not run tools.
    pub block_tools: bool,
    /// "Stop after this step" asked; the current turn is still finishing.
    pub stop_requested: bool,
    /// Paused: no new turn starts until you resume.
    pub paused: bool,
    /// Prompts and steer notes waiting for the resume.
    pub held: u32,
}

impl ControlState {
    pub fn is_default(&self) -> bool {
        *self == ControlState::default()
    }
}
